import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"尊嘉","description":"","frontmatter":{"title":"尊嘉","date":"2026-11-24T00:00:00.000Z","seq":43,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王褒","source_book":"楚辞","prev":{"text":"昭世","link":"/blogs/楚辞/昭世.html"},"next":{"text":"蓄英","link":"/blogs/楚辞/蓄英.html"}},"headers":[],"relativePath":"blogs/楚辞/尊嘉.md","filePath":"blogs/楚辞/尊嘉.md"}'),o={name:"blogs/楚辞/尊嘉.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="尊嘉" tabindex="-1">尊嘉 <a class="header-anchor" href="#尊嘉" aria-label="Permalink to &quot;尊嘉&quot;">​</a></h1><p class="poem-meta">先秦 · 王褒　·　九怀</p><div class="poem"><p class="poem-stanza">季春兮阳阳，列草兮成行。</p><p class="poem-stanza">余悲兮兰生，委积兮从横。</p><p class="poem-stanza">江离兮遗捐，辛夷兮挤臧。</p><p class="poem-stanza">伊思兮往古，亦多兮遭殃。</p><p class="poem-stanza">伍胥兮浮江，屈子兮沉湘。</p><p class="poem-stanza">运余兮念兹，心内兮怀伤。</p><p class="poem-stanza">望淮兮沛沛，滨流兮则逝。</p><p class="poem-stanza">榜舫兮下流，东注兮磕磕。</p><p class="poem-stanza">蛟龙兮导引，文鱼兮上濑。</p><p class="poem-stanza">抽蒲兮陈坐，援芙蕖兮为盖。</p><p class="poem-stanza">水跃兮余旌，继以兮微蔡。</p><p class="poem-stanza">云旗兮电骛，倏忽兮容裔。</p><p class="poem-stanza">河伯兮开门，迎余兮欢欣。</p><p class="poem-stanza">顾念兮旧都，怀恨兮艰难。</p><p class="poem-stanza">窃哀兮浮萍，汎淫兮无根。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
